/**
 * Site Footer -- section behaviour.
 *
 * GENERATED by tools/uew from shared/section-99-footer.html. Do not edit by hand.
 *
 * The section's original script bodies are reproduced verbatim inside
 * uewRun(). What is added around them is the Elementor lifecycle: widgets are
 * injected into the editor canvas long after DOMContentLoaded, so a bare IIFE
 * would query an element that does not exist yet and the section would look
 * "broken" in the editor. Registering on frontend/element_ready fixes that, and
 * the data-uew-ready latch keeps a double call harmless.
 */
( function () {
	'use strict';

	var ROOT_SELECTOR = "#umoya-footer";
	var WIDGET_NAME = "umoya-site-footer";

	var PORTAL_IDS = ["umoya-email-optout"];

	/*
	 * In the editor every control change re-renders the widget, bringing a
	 * fresh copy of each dialog that moves itself to <body> -- while the
	 * previous copy is still there, with the previous run's listeners still
	 * attached. A trigger would then open both: the fresh one on top and a
	 * stale one underneath that reappears when the fresh one is closed.
	 *
	 * Each copy outside the widget being initialised is retired before the
	 * section script runs again: hidden for good, and without its id so the
	 * script's getElementById() finds the fresh one. On a published page there
	 * is only ever one copy, so this does nothing there.
	 */
	function uewRetireStalePortals( scopeElement ) {
		for ( var i = 0; i < PORTAL_IDS.length; i++ ) {
			var copies = document.querySelectorAll( '[id="' + PORTAL_IDS[ i ] + '"]' );
			if ( copies.length < 2 ) {
				continue;
			}
			for ( var j = 0; j < copies.length; j++ ) {
				if ( scopeElement.contains( copies[ j ] ) ) {
					continue;
				}
				copies[ j ].removeAttribute( 'id' );
				copies[ j ].setAttribute( 'data-uew-retired', '1' );
				copies[ j ].style.setProperty( 'display', 'none', 'important' );
			}
		}
	}

	function uewRun() {
		(function(){
		  'use strict';

		  var root = document.getElementById('umoya-footer');
		  if (!root || root.getAttribute('data-ready') === 'true') return;
		  root.setAttribute('data-ready', 'true');

		  /* ── Full-bleed width, minus the scrollbar ──────────────────────
		   * See the note on --umoya-ft-vw in the CSS above. Throttled through rAF
		   * with a setTimeout fallback, because rAF never fires in non-compositing
		   * contexts and would otherwise latch the throttle permanently. */
		  var vwTick = 0;
		  function syncFullBleedWidth(){
		    document.documentElement.style.setProperty('--umoya-ft-vw', document.documentElement.clientWidth + 'px');
		  }
		  function scheduleWidthSync(){
		    if (vwTick) return;
		    if (window.requestAnimationFrame) {
		      vwTick = window.requestAnimationFrame(function(){ vwTick = 0; syncFullBleedWidth(); });
		    } else {
		      vwTick = window.setTimeout(function(){ vwTick = 0; syncFullBleedWidth(); }, 16);
		    }
		  }
		  syncFullBleedWidth();
		  window.addEventListener('resize', scheduleWidthSync);
		  window.addEventListener('orientationchange', scheduleWidthSync);
		  /* Late-loading images/fonts can introduce or remove the scrollbar */
		  window.setTimeout(syncFullBleedWidth, 800);

		  /* ── Current year ───────────────────────────────────────────── */
		  var yearEl = root.querySelector('[data-umoya-year]');
		  if (yearEl) yearEl.textContent = String(new Date().getFullYear());

		  /* ── Cookie preferences ─────────────────────────────────────────
		   * CookieYes owns this button via the .cky-banner-element class and
		   * binds its own click handler. The only job here is to stop the
		   * button being inert if CookieYes has not loaded — checked AT CLICK
		   * TIME, so when CookieYes is present this handler does nothing and
		   * lets the real preference centre open. */
		  var cookieBtn = root.querySelector('[data-umoya-cookie-prefs]');
		  if (cookieBtn) {
		    cookieBtn.addEventListener('click', function(){
		      var cookieYesPresent = !!(
		        window.CookieYes ||
		        window.cookieyes ||
		        document.querySelector('.cky-consent-container, .cky-modal, #cookieyes')
		      );
		      if (cookieYesPresent) return;
		      window.location.href = 'https://umoyaafrikatours.co.za/privacy/';
		    });
		  }

		  /* ── Founder's Circle signup ────────────────────────────────── */
		  var form = document.getElementById('umoyaFooterForm');
		  if (!form) return;

		  var btn = document.getElementById('umoyaFtSubmit');
		  var statusEl = form.querySelector('.umoya-ft-status');
		  var originalText = btn ? btn.textContent : 'Join';
		  var submitting = false;

		  /* Shared with the other Umoya forms — all flush to the same endpoint */
		  var pendingBackupKey = 'umoyaPendingBackups';
		  var pendingBackupMaxAge = 1000 * 60 * 60 * 24 * 3;

		  /* Only two properties; both resolve through the DEFAULT alias table in
		     class-submissions.php, so this form needs no server-side change. */
		  var hubspotFieldMap = {
		    FNAME: 'firstname',
		    EMAIL: 'email'
		  };

		  function isValidEmail(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }

		  function getFieldValue(name){
		    var f = form.elements[name];
		    return f ? String(f.value || '').trim() : '';
		  }

		  function getCookie(name){
		    var parts = document.cookie ? document.cookie.split('; ') : [];
		    for (var i = 0; i < parts.length; i += 1) {
		      var item = parts[i].split('=');
		      if (item[0] === name) return decodeURIComponent(item.slice(1).join('='));
		    }
		    return '';
		  }

		  function setHidden(name, value){
		    var f = form.elements ? form.elements[name] : null;
		    if (f) f.value = value || '';
		  }

		  function syncTrackingFields(){
		    setHidden('hutk', getCookie('hubspotutk'));
		    setHidden('pageUri', window.location.href);
		    setHidden('pageName', document.title || 'Umoya Afrika Tours');
		  }

		  function identifyHubSpotVisitor(){
		    var email = getFieldValue('EMAIL');
		    if (!email || !isValidEmail(email)) return;
		    window._hsq = window._hsq || [];
		    window._hsq.push(['identify', { email: email }]);
		    window._hsq.push(['trackPageView']);
		  }

		  function showStatus(msg, isError){
		    if (!statusEl) return;
		    statusEl.textContent = msg;
		    statusEl.classList.toggle('is-error', !!isError);
		    statusEl.classList.add('is-visible');
		  }

		  function buildHubSpotPayload(){
		    syncTrackingFields();
		    var fields = [];
		    Object.keys(hubspotFieldMap).forEach(function(name){
		      var v = getFieldValue(name);
		      if (v) fields.push({ name: hubspotFieldMap[name], value: v });
		    });

		    var context = { pageUri: window.location.href, pageName: document.title || 'Umoya Afrika Tours' };
		    var hutk = getCookie('hubspotutk');
		    if (hutk) context.hutk = hutk;

		    var payload = { fields: fields, context: context };

		    /* Record the exact wording the subscriber agreed to, for the
		       POPIA consent register. */
		    var consentText = (form.getAttribute('data-hubspot-consent-text') || '').trim();
		    if (consentText) {
		      payload.legalConsentOptions = { consent: { consentToProcess: true, text: consentText } };
		    }
		    return payload;
		  }

		  function createSubmissionId(){
		    if (window.crypto && typeof window.crypto.randomUUID === 'function') return window.crypto.randomUUID();
		    return 'umoya-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12);
		  }

		  function buildBackupPayload(){
		    var hs = buildHubSpotPayload();
		    var raw = {};
		    Object.keys(hubspotFieldMap).forEach(function(n){ raw[n] = getFieldValue(n); });

		    /* Submitting the form IS the affirmative act the fine print describes,
		       so consent is recorded as given — alongside the exact wording. */
		    raw.marketing_opt_in = 'yes';
		    raw.consent_to_process = 'yes';

		    return {
		      submissionId: createSubmissionId(),
		      source: (form.getAttribute('data-umoya-form-source') || 'footer_newsletter').trim(),
		      hubspotPortalId: (form.getAttribute('data-hubspot-portal-id') || '').trim(),
		      hubspotFormId: (form.getAttribute('data-hubspot-form-id') || '').trim(),
		      consentText: (form.getAttribute('data-hubspot-consent-text') || '').trim(),
		      hutk: getCookie('hubspotutk'),
		      pageUri: window.location.href,
		      pageName: document.title || 'Umoya Afrika Tours',
		      rawFields: raw,
		      fields: hs.fields,
		      context: hs.context
		    };
		  }

		  function getPendingBackups(){
		    try {
		      return JSON.parse(window.localStorage.getItem(pendingBackupKey) || '[]').filter(function(i){
		        return i && (!i.queuedAt || Date.now() - i.queuedAt < pendingBackupMaxAge);
		      });
		    } catch (ignore) { return []; }
		  }

		  function savePendingBackups(items){
		    try { window.localStorage.setItem(pendingBackupKey, JSON.stringify(items.slice(-8))); } catch (ignore) {}
		  }

		  function queuePendingBackup(payload){
		    payload.hubspotAlreadySent = true;
		    payload.queuedAt = Date.now();
		    var items = getPendingBackups();
		    items.push(payload);
		    savePendingBackups(items);
		  }

		  function flushPendingBackups(){
		    var items = getPendingBackups();
		    if (!items.length) return;
		    var endpoint = (form.getAttribute('data-wordpress-backup-endpoint') || '/wp-json/umoya/v1/submissions').trim();
		    var remaining = items.slice();

		    items.forEach(function(item){
		      fetch(endpoint, {
		        method: 'POST',
		        headers: { 'Content-Type': 'application/json' },
		        credentials: 'same-origin',
		        body: JSON.stringify(item)
		      }).then(function(res){
		        if (!res.ok) return;
		        remaining = remaining.filter(function(e){ return e.submissionId !== item.submissionId; });
		        savePendingBackups(remaining);
		      }).catch(function(){});
		    });
		  }

		  function submitToHubSpot(){
		    var portalId = (form.getAttribute('data-hubspot-portal-id') || '').trim();
		    var formId = (form.getAttribute('data-hubspot-form-id') || '').trim();
		    if (!portalId || !formId) return Promise.reject(new Error('HubSpot is not configured yet.'));

		    return fetch('https://api.hsforms.com/submissions/v3/integration/submit/' + encodeURIComponent(portalId) + '/' + encodeURIComponent(formId), {
		      method: 'POST',
		      headers: { 'Content-Type': 'application/json' },
		      body: JSON.stringify(buildHubSpotPayload())
		    }).then(function(res){
		      return res.text().then(function(text){
		        var data = null;
		        if (text) { try { data = JSON.parse(text); } catch (ignore) {} }
		        if (!res.ok) {
		          throw new Error(data && (data.message || data.error) ? (data.message || data.error) : 'HubSpot could not receive the signup.');
		        }
		        return data;
		      });
		    });
		  }

		  function submitToWordPress(payload){
		    var endpoint = (form.getAttribute('data-wordpress-backup-endpoint') || '/wp-json/umoya/v1/submissions').trim();
		    return fetch(endpoint, {
		      method: 'POST',
		      headers: { 'Content-Type': 'application/json' },
		      credentials: 'same-origin',
		      body: JSON.stringify(payload)
		    }).then(function(res){
		      return res.text().then(function(text){
		        var data = null;
		        if (text) { try { data = JSON.parse(text); } catch (ignore) {} }
		        if (!res.ok || !data || data.saved !== true) {
		          throw new Error(data && data.message ? data.message : 'WordPress could not save the signup.');
		        }
		        return data;
		      });
		    });
		  }

		  function showSuccess(){
		    if (btn) {
		      btn.disabled = true;
		      btn.textContent = 'Welcome';
		    }
		    showStatus('Thank you. Look out for our next letter.', false);
		  }

		  function showError(msg){
		    submitting = false;
		    if (btn) { btn.disabled = false; btn.textContent = originalText; }
		    showStatus(msg, true);
		  }

		  syncTrackingFields();
		  window.setTimeout(syncTrackingFields, 1500);
		  window.setTimeout(flushPendingBackups, 1400);

		  form.addEventListener('submit', function(e){
		    e.preventDefault();
		    if (submitting) return;

		    syncTrackingFields();

		    var emailField = form.querySelector('[name="EMAIL"]');
		    if (!emailField.value.trim() || !isValidEmail(emailField.value)) {
		      emailField.style.borderColor = '#D97E53';
		      emailField.style.boxShadow = '0 0 0 3px rgba(217,126,83,.28)';
		      showStatus('Please enter a valid email address.', true);
		      emailField.focus();
		      return;
		    }

		    submitting = true;
		    if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
		    showStatus('Signing you up…', false);
		    identifyHubSpotVisitor();

		    var payload = buildBackupPayload();

		    /* WordPress first (it stores + forwards); direct HubSpot is the fallback */
		    submitToWordPress(payload)
		      .then(showSuccess)
		      .catch(function(err){
		        submitToHubSpot()
		          .then(function(){ queuePendingBackup(payload); showSuccess(); })
		          .catch(function(fallbackErr){
		            showError((err.message || 'Could not save the signup.') + ' ' + (fallbackErr.message || ''));
		          });
		      });
		  });

		  form.querySelectorAll('input').forEach(function(f){
		    f.addEventListener('input', function(){
		      f.style.borderColor = '';
		      f.style.boxShadow = '';
		      if (statusEl) statusEl.classList.remove('is-visible', 'is-error');
		    });
		  });
		}());

		(function(){
		  'use strict';

		  var popup = document.getElementById('umoya-email-optout');
		  if (!popup || popup.getAttribute('data-ready') === 'true') return;
		  popup.setAttribute('data-ready', 'true');

		  var dialog = popup.querySelector('.umoya-ep-dialog');
		  var closeBtn = popup.querySelector('[data-umoya-ep-close]');
		  var lastFocus = null;
		  var closeTimer = 0;

		  /* See the header note: fixed positioning is only reliable against the
		     viewport when the element is not inside a transformed ancestor. */
		  function moveToBody(){
		    if (popup.parentElement !== document.body) document.body.appendChild(popup);
		  }
		  moveToBody();

		  function focusable(){
		    return dialog.querySelectorAll(
		      'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
		    );
		  }

		  function onKeydown(e){
		    var key = e.key;

		    if (key === 'Escape' || key === 'Esc') {
		      closePopup();
		      return;
		    }

		    if (key !== 'Tab') return;

		    /* Focus trap. Without it Tab walks out of the dialog and into the page
		       behind, which aria-modal only hides from assistive tech — it does not
		       stop the keyboard. */
		    var items = focusable();
		    if (!items.length) return;
		    var first = items[0];
		    var last = items[items.length - 1];
		    var active = document.activeElement;

		    /* Focus is outside the dialog — pull it back in. Not merely defensive:
		       the trigger link still holds focus for the moment between opening and
		       the close button receiving it, and a Tab in that window would
		       otherwise walk straight off into the page behind. */
		    if (!dialog.contains(active)) {
		      e.preventDefault();
		      (e.shiftKey ? last : first).focus();
		      return;
		    }

		    if (e.shiftKey && active === first) {
		      e.preventDefault();
		      last.focus();
		    } else if (!e.shiftKey && active === last) {
		      e.preventDefault();
		      first.focus();
		    }
		  }

		  function openPopup(){
		    lastFocus = document.activeElement;
		    moveToBody();
		    if (closeTimer) { window.clearTimeout(closeTimer); closeTimer = 0; }
		    /* Drop the hard hide, then force a reflow so the browser has a starting
		       frame to transition FROM — without it the fade is skipped. */
		    popup.hidden = false;
		    /* eslint-disable-next-line no-unused-expressions */
		    popup.offsetHeight;
		    popup.classList.add('is-open');
		    popup.setAttribute('aria-hidden', 'false');
		    /*
		     * Same scroll lock as the homepage popup. Note this removes the
		     * scrollbar, which widens documentElement.clientWidth — but the footer
		     * only re-reads that on resize, so --umoya-ft-vw keeps its
		     * scrollbar-excluded value and the full-bleed footer does NOT regain
		     * the horizontal-scrollbar bug documented in _NOTES 9.
		     */
		    document.documentElement.style.overflow = 'hidden';
		    document.body.style.overflow = 'hidden';
		    document.addEventListener('keydown', onKeydown);
		    /* Focus straight away; the timeout is only a safety net for engines that
		       will not focus an element whose visibility flipped in this same tick. */
		    if (closeBtn) closeBtn.focus();
		    window.setTimeout(function(){
		      if (closeBtn && !dialog.contains(document.activeElement)) closeBtn.focus();
		    }, 40);
		  }

		  function closePopup(){
		    if (!popup.classList.contains('is-open')) return;
		    popup.classList.remove('is-open');
		    popup.setAttribute('aria-hidden', 'true');
		    document.documentElement.style.overflow = '';
		    document.body.style.overflow = '';
		    document.removeEventListener('keydown', onKeydown);
		    if (lastFocus && typeof lastFocus.focus === 'function') lastFocus.focus();
		    lastFocus = null;
		    /* Restore the hard hide once the fade has finished. */
		    if (closeTimer) window.clearTimeout(closeTimer);
		    closeTimer = window.setTimeout(function(){
		      closeTimer = 0;
		      if (!popup.classList.contains('is-open')) popup.hidden = true;
		    }, 320);
		  }

		  if (closeBtn) closeBtn.addEventListener('click', closePopup);

		  /* Backdrop click — only when the press AND the release both land on the
		     backdrop, so selecting the email address and releasing outside the
		     dialog does not close it. */
		  var downOnBackdrop = false;
		  popup.addEventListener('mousedown', function(e){ downOnBackdrop = (e.target === popup); });
		  popup.addEventListener('click', function(e){
		    if (e.target === popup && downOnBackdrop) closePopup();
		    downOnBackdrop = false;
		  });

		  /*
		   * Triggers. The footer's Email Opt-out link carries
		   * data-umoya-email-optout; any other element on any page can opt in the
		   * same way. Bound per element rather than through a document-level
		   * listener, per the project's no-blanket-global rule.
		   *
		   * The trigger keeps a real mailto href, so with JS unavailable the item
		   * still does what it says. preventDefault() only runs once this script
		   * is live.
		   */
		  var triggers = document.querySelectorAll('[data-umoya-email-optout]');
		  Array.prototype.forEach.call(triggers, function(t){
		    t.addEventListener('click', function(e){
		      e.preventDefault();
		      openPopup();
		    });
		  });
		}());
	}

	function uewInit( scope ) {
		var context = scope && scope.length ? scope[ 0 ] : ( scope || document );
		var root = context.querySelector ? context.querySelector( ROOT_SELECTOR ) : null;

		if ( ! root && context !== document && context.matches && context.matches( ROOT_SELECTOR ) ) {
			root = context;
		}
		if ( ! root ) {
			root = document.querySelector( ROOT_SELECTOR );
		}
		if ( ! root ) {
			return;
		}
		if ( root && root.getAttribute( 'data-uew-ready' ) === '1' ) {
			return;
		}
		if ( root ) {
			root.setAttribute( 'data-uew-ready', '1' );
		}

		if ( context !== document && context.contains ) {
			uewRetireStalePortals( context );
		}

		uewRun();
	}

	function uewRegister() {
		if ( ! window.elementorFrontend || ! window.elementorFrontend.hooks ) {
			return false;
		}
		window.elementorFrontend.hooks.addAction( 'frontend/element_ready/' + WIDGET_NAME + '.default', uewInit );
		return true;
	}

	if ( ! uewRegister() ) {
		// Elementor fires this through jQuery, not as a native DOM event, so a
		// plain addEventListener would never hear it.
		if ( window.jQuery ) {
			window.jQuery( window ).on( 'elementor/frontend/init', uewRegister );
		} else {
			window.addEventListener( 'elementor/frontend/init', uewRegister );
		}
	}

	// Plain page load (and any context where Elementor's frontend never boots).
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', function () {
			uewInit( document );
		} );
	} else {
		uewInit( document );
	}
}() );
